import json, sys
data = json.load(sys.stdin)
registry = json.loads(data['result'])['data']
# Show experiments by status
by_status = {}
for exp in registry:
    s = exp.get('status','?')
    if s not in by_status:
        by_status[s] = []
    by_status[s].append({'id': exp.get('exp_id'), 'conclusion': exp.get('conclusion'), 'hypothesis': exp.get('hypothesis','')[:80]})
for status in ['RUNNING','PREPARING','PENDING','QUEUED','ALLOCATED']:
    if status in by_status:
        print(f'\n=== {status} ===')
        for e in by_status[status]:
            print(f\"  {e['id']}: {e['conclusion']} | {e['hypothesis']}\")
print(f'\n=== SUMMARY ===')
for s, exps in sorted(by_status.items()):
    print(f'  {s}: {len(exps)}')
